<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='contact-lens-orders';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){$beneficiary=filter_input(INPUT_POST,'beneficiary_id',FILTER_VALIDATE_INT);$power=filter_input(INPUT_POST,'requested_power',FILTER_VALIDATE_FLOAT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$beneficiary||$power===false||$power<-30||$power>30)$errors[]='Select a beneficiary and valid lens power.';if(!$errors){try{$check=$db->prepare("SELECT id FROM beneficiaries WHERE id=:id AND status='active'");$check->execute(['id'=>$beneficiary]);if(!$check->fetchColumn())throw new RuntimeException('Beneficiary is unavailable.');$pending=$db->prepare("SELECT COUNT(*) FROM contact_lens_orders WHERE beneficiary_id=:beneficiary AND status IN ('pending','approved','procurement-required')");$pending->execute(['beneficiary'=>$beneficiary]);if($pending->fetchColumn())throw new RuntimeException('This beneficiary already has an active lens order.');$stmt=$db->prepare('INSERT INTO contact_lens_orders(beneficiary_id,requested_power,submitted_by) VALUES(:beneficiary,:power,:user)');$stmt->execute(['beneficiary'=>$beneficiary,'power'=>number_format((float)$power,2,'.',''),'user'=>$_SESSION['user_id']]);$id=(int)$db->lastInsertId();logActivity('Contact Lenses','Submitted contact lens order','CL-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'pending');$_SESSION['flash_success']='Contact lens order submitted.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=contact-lens-orders');exit;}catch(Throwable $e){error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to submit lens order.';}}}
try{$beneficiaries=$db->query("SELECT id,full_name,nic FROM beneficiaries WHERE status='active' ORDER BY full_name")->fetchAll();$stmt=$db->prepare('SELECT o.*,b.full_name,b.nic FROM contact_lens_orders o JOIN beneficiaries b ON b.id=o.beneficiary_id WHERE o.submitted_by=:user ORDER BY o.id DESC');$stmt->execute(['user'=>$_SESSION['user_id']]);$rows=$stmt->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$beneficiaries=$rows=[];$errors[]='Contact lens workflow is unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact Lens Orders | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Contact Lens Orders</h1></div></header><main class="dashboard-content admin-operation-page"><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>New Contact Lens Order</h2></div><form method="post" class="master-inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Beneficiary<select name="beneficiary_id" required><option value="">Select beneficiary</option><?php foreach($beneficiaries as $b):?><option value="<?=(int)$b['id']?>"><?=htmlspecialchars($b['full_name'].' — '.$b['nic'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Requested Power<input type="number" name="requested_power" min="-30" max="30" step="0.25" required></label><button class="admin-primary-action">Submit Order</button></form></section><section class="admin-data-card operation-list-card"><div class="admin-data-header"><h2>My Contact Lens Orders</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>ID</th><th>Beneficiary</th><th>NIC</th><th>Requested Power</th><th>Current Power</th><th>Power Changed?</th><th>Status</th><th>Date</th><th>Reason</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="admin-empty-row">No contact lens orders available.</td></tr><?php else:foreach($rows as $r):?><tr><td>CL-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['nic'],ENT_QUOTES,'UTF-8')?></td><td><?=number_format((float)$r['requested_power'],2)?></td><td><?=$r['current_power']!==null?number_format((float)$r['current_power'],2):'—'?></td><td><?=$r['current_power']!==null&&(float)$r['current_power']!==(float)$r['requested_power']?'Yes':'No'?></td><td><?=ucwords(str_replace('-',' ',$r['status']))?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($r['rejection_reason']?:'—',ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
